shapes.code:
// A discriminated union: the `kind` tag lets the checker narrow each case.
type Shape =
  | { kind: "Rectangle"; width: number; height: number }
  | { kind: "Triangle"; base: number; height: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "Rectangle":
      return shape.width * shape.height;
    case "Triangle":
      return (shape.base * shape.height) / 2;
    default: {
      const unreachable: never = shape; // compile error if a case is missing
      return unreachable;
    }
  }
}

const shapes: Shape[] = [
  { kind: "Rectangle", width: 3, height: 4 },
  { kind: "Triangle", base: 10, height: 3 },
];

for (const s of shapes) console.log(`${s.kind}: ${area(s)}`);

