interface Point { x: number; y: number }

// Structural: anything with numeric x and y is a Point; no `implements` needed.
const norm = (p: Point): number => Math.hypot(p.x, p.y);
const pixel = { x: 3, y: 4, color: "red" };
console.log(norm(pixel));

// Type-level programming: compute a new type from an old one.
type Getters<T> = {
  [K in keyof T & string as `get${Capitalize<K>}`]: () => T[K];
};

function getters<T extends object>(obj: T): Getters<T> {
  const out: Record<string, () => unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    out[`get${k[0].toUpperCase()}${k.slice(1)}`] = () => v;
  }
  return out as Getters<T>;
}

const g = getters(pixel); // { getX: () => number; getY: () => number; getColor: () => string }
console.log(g.getColor(), g.getX() * g.getY());
